import axios from "axios";

let store: any;
export const injectStore = (_store: any) => {
    store = _store
}


export const createAxiosInstance = () => {
    const instance = axios.create({
        //baseURL: 'http://localhost:5000/api/',
        //baseURL: 'https://80.90.184.43/api/',
        baseURL: 'http://80.90.184.43/api/',
        headers: {
            'Content-Type': 'application/json',
        },
    });

    // Добавляем перехватчик запроса для добавления Bearer токена из local storage
    instance.interceptors.request.use(
        (config) => {
            const token = store.getState().tokenSlice.token;
            if (token) {
                config.headers.Authorization = `Bearer ${token}`;
            }
            return config;
        },
        (error) => {
            return Promise.reject(error);
        }
    );

    return instance;
};


const axiosInstance = createAxiosInstance();

export const authApi = {
    getToken: (initData: string) => {
        return axiosInstance.get('/users/login', {params: {initData: initData}});
    },
    getMyData: () => {
        return axiosInstance.get('/users/auth/me');
    },
    getOwnOperations: () => {
        return axiosInstance.get('/users/get-own-operations')
    },
    createWithdrawReq: (data: { sum: string, operation: string, comment: string }) => {
        return axiosInstance.post('/users/balance-req', data)
    }
}
